param([string]$Root=(Resolve-Path '.').Path)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$FrameSize=256
function NewBmp($w,$h){$b=New-Object System.Drawing.Bitmap -ArgumentList @($w,$h,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[System.Drawing.Graphics]::FromImage($b);$g.Clear([System.Drawing.Color]::Transparent);$g.Dispose();$b}
function Extract($sheetPath,$index){$src=[System.Drawing.Bitmap]::FromFile($sheetPath);try{$dst=NewBmp $FrameSize $FrameSize;$g=[System.Drawing.Graphics]::FromImage($dst);$g.InterpolationMode=[System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor;$g.PixelOffsetMode=[System.Drawing.Drawing2D.PixelOffsetMode]::Half;$col=$index % 4;$row=[Math]::Floor($index / 4);$sx=[int]($col*$FrameSize);$sy=[int]($row*$FrameSize);$sr=New-Object System.Drawing.Rectangle -ArgumentList @($sx,$sy,$FrameSize,$FrameSize);$dr=New-Object System.Drawing.Rectangle -ArgumentList @(0,0,$FrameSize,$FrameSize);$g.DrawImage($src,$dr,$sr,[System.Drawing.GraphicsUnit]::Pixel);$g.Dispose();$dst}finally{$src.Dispose()}}
function Bounds($bmp){$minx=$bmp.Width;$miny=$bmp.Height;$maxx=-1;$maxy=-1;for($y=0;$y -lt $bmp.Height;$y++){for($x=0;$x -lt $bmp.Width;$x++){if($bmp.GetPixel($x,$y).A -gt 0){if($x -lt $minx){$minx=$x};if($y -lt $miny){$miny=$y};if($x -gt $maxx){$maxx=$x};if($y -gt $maxy){$maxy=$y}}}};[pscustomobject]@{MinX=$minx;MinY=$miny;MaxX=$maxx;MaxY=$maxy}}
function Rotate($bmp,[double]$deg,[int]$ox,[int]$oy){$bd=Bounds $bmp;$cx=($bd.MinX+$bd.MaxX)/2.0;$cy=($bd.MinY+$bd.MaxY)/2.0;$rad=$deg*[Math]::PI/180.0;$cos=[Math]::Cos($rad);$sin=[Math]::Sin($rad);$out=NewBmp $bmp.Width $bmp.Height;for($ny=0;$ny -lt $bmp.Height;$ny++){for($nx=0;$nx -lt $bmp.Width;$nx++){$dx=$nx-$ox-$cx;$dy=$ny-$oy-$cy;$sx=[int][Math]::Round(($dx*$cos)+($dy*$sin)+$cx);$sy=[int][Math]::Round((-1*$dx*$sin)+($dy*$cos)+$cy);if($sx -ge 0 -and $sy -ge 0 -and $sx -lt $bmp.Width -and $sy -lt $bmp.Height){$p=$bmp.GetPixel($sx,$sy);if($p.A -gt 0){$out.SetPixel($nx,$ny,$p)}}}};$out}
$base=Extract (Join-Path $Root 'assets\generated\rika\dash.png') 5
try{$alt=Rotate $base -10 8 10;try{$path=Join-Path $Root 'tmp\rika_dash_frame_07_corrected_alt.png';if(Test-Path $path){Remove-Item $path -Force};$alt.Save($path,[System.Drawing.Imaging.ImageFormat]::Png);Write-Host $path}finally{$alt.Dispose()}}finally{$base.Dispose()}
